import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import backgroundImage from "../Img/order6.jpg";

const UpdateOrder = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [order, setOrder] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    address: "",
    city: "",
    orderId: "",
    specialInstructions: "",
    pickupTime: "",
    orderStatus: "",
  });

  const [errors, setErrors] = useState({});

  useEffect(() => {
    const fetchOrder = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/orders/${id}`);
        setOrder(res.data.order || {});
      } catch (err) {
        console.error("Error fetching order:", err);
      }
    };
    fetchOrder();
  }, [id]);

  const validateForm = () => {
    let newErrors = {};

    // Validation for required fields
    if (!order.firstName.trim()) newErrors.firstName = "First Name is required.";
    if (!order.lastName.trim()) newErrors.lastName = "Last Name is required.";
    if (!order.email.trim()) {
      newErrors.email = "Email is required.";
    } else if (!/\S+@\S+\.\S+/.test(order.email)) {
      newErrors.email = "Enter a valid email address.";
    }
    if (!order.phoneNumber.trim()) {
      newErrors.phoneNumber = "Phone Number is required.";
    } else if (!/^\d{10}$/.test(order.phoneNumber)) {
      newErrors.phoneNumber = "Phone Number must be exactly 10 digits and contain no letters or special characters.";
    }
    if (!order.address.trim()) newErrors.address = "Address is required.";
    if (!order.city.trim()) newErrors.city = "City is required.";
    if (!order.orderId.trim()) newErrors.orderId = "Order ID is required.";
    
    // Pickup time validation
    if (!order.pickupTime.trim()) {
      newErrors.pickupTime = "Pickup Time is required.";
    } else {
      const currentTime = new Date();
      const selectedTime = new Date(order.pickupTime);
      if (selectedTime <= currentTime) {
        newErrors.pickupTime = "Pickup Time must be in the future.";
      }
    }

    if (!order.orderStatus.trim()) newErrors.orderStatus = "Order Status is required.";

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    // Ensure the phone number only allows digits
    if (e.target.name === "phoneNumber" && !/^\d*$/.test(e.target.value)) {
      return; // Only allow numbers
    }

    setOrder({ ...order, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    try {
      await axios.put(`http://localhost:5000/orders/${id}`, order);
      alert("Order updated successfully!");
      navigate("/all-orders");
    } catch (error) {
      console.error("Error updating order:", error);
      alert("Failed to update the order. Try again.");
    }
  };

  if (!order || Object.keys(order).length === 0) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading order details...</div>;
  }

  return (
    <div
      style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        minHeight: "100vh",
        backgroundColor: "#f0f0f0",
        backgroundImage: `url(${backgroundImage})`,
        backgroundSize: "cover",
        backgroundRepeat: "no-repeat",
        backgroundBlendMode: "multiply",
      }}
    >
      <div
        style={{
          backgroundColor: "rgba(255, 255, 255, 0.7)",
          padding: "20px",
          borderRadius: "10px",
          boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
          width: "100%",
          maxWidth: "600px",
          boxSizing: "border-box",
        }}
      >
        <h2 style={{ textAlign: "center", color: "#8B0000", fontWeight: "bold", marginBottom: "20px" }}>
          Update Order
        </h2>
        <form onSubmit={handleSubmit}>
          {Object.keys(order).map((key) => (
            <div key={key} style={{ marginBottom: "15px" }}>
              <label style={{ display: "block", fontWeight: "bold" }}>
                {key.replace(/([A-Z])/g, " $1").trim()}
              </label>
              <input
                type="text"
                name={key}
                value={order[key] || ""}
                onChange={handleChange}
                style={{
                  width: "100%",
                  padding: "10px",
                  borderRadius: "4px",
                  border: "1px solid #ccc",
                  boxSizing: "border-box",
                }}
              />
              {errors[key] && <p style={{ color: "red", fontSize: "14px" }}>{errors[key]}</p>}
            </div>
          ))}
          <button
            type="submit"
            style={{
              backgroundColor: "#b30000",
              color: "white",
              padding: "10px 20px",
              border: "none",
              borderRadius: "5px",
              cursor: "pointer",
              fontSize: "16px",
              width: "100%",
              marginBottom: "10px",
            }}
          >
            Update Order
          </button>
        </form>
        <button
          onClick={() => navigate("/all-orders")}
          style={{
            backgroundColor: "#dc2626",
            color: "white",
            padding: "10px 20px",
            border: "none",
            borderRadius: "5px",
            cursor: "pointer",
            fontSize: "16px",
            width: "100%",
          }}
        >
          Cancel
        </button>
      </div>
    </div>
  );
};

export default UpdateOrder;
